// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');

// Module-level font loading
const { fontFamily: montserratFamily } = loadMontserrat();



export type ClockAnimationProps = Record<string, any>;

const ClockAnimation: React.FC<ClockAnimationProps> = ({
  backgroundColor = "#040D26",
  transparentBackground = false,
  durationInSeconds = 6,
  clockFaceColor = "#FFFFFF",
  clockBorderColor = "#F3F4F6",
  clockHandColor = "#0A1B43",
  accentColor = "#2AC5C6",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timings
  const startEntrance = 5;

  // Entrance Animations
  const clockScale = spring({
    frame: frame - startEntrance,
    fps,
    config: { damping: 14, mass: 0.8 },
  });

  // Main Spin Animation (Linear, continuous till the end of the duration)
  const spinProgress = interpolate(
    frame,
    [startEntrance, durationInSeconds * fps],
    [0, 1],
    {
      extrapolateLeft: "clamp",
      extrapolateRight: "clamp",
    }
  );

  // Hour and Minute Hand Rotations
  // Let the minute hand make 12 full rotations over the course of the duration, and the hour hand rotate 1 full time (1/12th speed)
  const totalMinuteRotations = 12;
  const minuteRotation = spinProgress * totalMinuteRotations * 360;
  const hourRotation = minuteRotation / 12;

  // Clock configuration
  const clockSize = 800 * s;
  const cx = 500;
  const cy = 500;
  const outerRadius = 480;
  const innerRadius = 430;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        fontFamily: montserratFamily,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {/* Clock Face Container */}
      <div
        style={{
          width: clockSize,
          height: clockSize,
          transform: `scale(${clockScale})`,
          opacity: clockScale > 0 ? clockScale : 0,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
        }}
      >
        <svg
          viewBox="0 0 1000 1000"
          style={{ width: "100%", height: "100%", overflow: "visible" }}
        >
          {/* Background Circles */}
          <circle cx={cx} cy={cy} r={outerRadius} fill={clockBorderColor} />
          <circle cx={cx} cy={cy} r={innerRadius} fill={clockFaceColor} />

          {/* Static Tick Marks */}
          {Array.from({ length: 60 }).map((_, i) => {
            const angleDeg = i * 6 - 90;
            const rad = angleDeg * (Math.PI / 180);

            const isHour = i % 5 === 0;
            const isHighlighted = i > 0 && i <= 15; // Highlight first 15 mins (90 degrees) roughly matching reference

            const tickLength = isHour ? 36 : 18;
            const tickThickness = isHour ? 12 : 4;
            const tickColor = isHighlighted ? accentColor : clockHandColor;

            // Offset the minute markers slightly inward to match reference spacing
            const radiusOffset = isHour ? 0 : 8;
            const rStart = innerRadius - 20 - radiusOffset;
            const rEnd = rStart - tickLength;

            const x1 = cx + rStart * Math.cos(rad);
            const y1 = cy + rStart * Math.sin(rad);
            const x2 = cx + rEnd * Math.cos(rad);
            const y2 = cy + rEnd * Math.sin(rad);

            return (
              <line
                key={`tick-${i}`}
                x1={x1}
                y1={y1}
                x2={x2}
                y2={y2}
                stroke={tickColor}
                strokeWidth={tickThickness}
                strokeLinecap="round"
                opacity={isHour ? 1 : isHighlighted ? 1 : 0.6}
              />
            );
          })}

          {/* Hour Hand Layer */}
          <g style={{ transform: `rotate(${hourRotation}deg)`, transformOrigin: `${cx}px ${cy}px` }}>
            {/* Hour Hand Shadow/Accent (Offset slightly) */}
            <line
              x1={cx}
              y1={cy}
              x2={cx}
              y2={cy - (innerRadius - 260)}
              stroke={accentColor}
              strokeWidth={24}
              strokeLinecap="round"
              transform="translate(8, 6)"
            />
            {/* Main Hour Hand */}
            <line
              x1={cx}
              y1={cy}
              x2={cx}
              y2={cy - (innerRadius - 260)}
              stroke={clockHandColor}
              strokeWidth={28}
              strokeLinecap="round"
            />
          </g>

          {/* Minute Hand Layer */}
          <g style={{ transform: `rotate(${minuteRotation}deg)`, transformOrigin: `${cx}px ${cy}px` }}>
            {/* Minute Hand Shadow/Accent (Offset slightly) */}
            <line
              x1={cx}
              y1={cy}
              x2={cx}
              y2={cy - (innerRadius - 120)}
              stroke={accentColor}
              strokeWidth={14}
              strokeLinecap="round"
              transform="translate(10, 8)"
            />
            {/* Main Minute Hand */}
            <line
              x1={cx}
              y1={cy}
              x2={cx}
              y2={cy - (innerRadius - 120)}
              stroke={clockHandColor}
              strokeWidth={18}
              strokeLinecap="round"
            />
          </g>

          {/* Center Dot */}
          <circle cx={cx} cy={cy} r={32} fill={clockHandColor} />
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default ClockAnimation;